/** Equirectangulaire : latitude/longitude -> coordonnees x/y dans le viewBox 1000x500. */
function gmProject(lat, lon) {
  const x = (lon + 180) / 360 * 1000;
  const y = (90 - lat) / 180 * 500;
  return [x, y];
}

