// Auparavant plafonne a 30 evenements peu importe leur age, ce qui rendait le
// chiffre affiche incomprehensible ("30" ne voulait rien dire de precis). Une
// vraie fenetre temporelle rend le total lisible : "visites des 5 dernieres
// minutes" est une phrase qui a un sens, contrairement a "les 30 derniers,
// quelle que soit leur anciennete".
const GM_WINDOW_MS = 5 * 60_000;

const GM_CATEGORY_COLOR = { human:'#00e87a', good:'#3b9eff', ai:'#b06bff', bad:'#ff4d6a', unknown:'#9ba3b8' };
const GM_CATEGORY_LABEL = { human:'Humain', good:'Bon robot', ai:'Robot IA', bad:'Robot indesirable', unknown:'Robot non identifie' };
// Fonction traduite (pas un objet fige, pour refleter la langue courante a
// chaque appel meme apres un changement via setLang()) : utilisee par la
// carte ET par la page Analyse (public/assets/js/analyzer.js), qui a
// rejoint ce mecanisme lors de son propre passage a l i18n. GM_CATEGORY_LABEL
// ci-dessus ne sert plus que de repli si jamais une cle geomap.legend.*
// venait a manquer.
function gmCategoryLabel(category) {
  return t('geomap.legend.' + (category || 'unknown')) || GM_CATEGORY_LABEL[category] || category || '—';
}

