function gmDrawGraticule() {
  const svg = document.getElementById('gm-svg');
  if (!svg || gmSvgReady) return;
  const g = svg.querySelector('g');
  let out = '';

  out += `<path d="${GM_WORLD_PATH}" fill="#2a6b4a" fill-opacity="0.45" stroke="#3a8a63" stroke-width="0.5" stroke-opacity="0.6"/>`;

  // Meridians and parallels, bright enough to actually read as a grid.
  for (let lon = -180; lon <= 180; lon += 30) {
    const [x] = gmProject(0, lon);
    out += `<line x1="${x}" y1="0" x2="${x}" y2="500" stroke="#ffffff28" stroke-width="1"/>`;
    if (lon !== -180 && lon !== 180) {
      out += `<text x="${x+3}" y="12" fill="#5a6278" font-size="9" font-family="monospace">${lon}°</text>`;
    }
  }
  for (let lat = -60; lat <= 60; lat += 30) {
    const [, y] = gmProject(lat, 0);
    out += `<line x1="0" y1="${y}" x2="1000" y2="${y}" stroke="#ffffff28" stroke-width="1"/>`;
    if (lat !== 0) out += `<text x="4" y="${y-3}" fill="#5a6278" font-size="9" font-family="monospace">${lat}°</text>`;
  }
  const [, eqY] = gmProject(0, 0);
  out += `<line x1="0" y1="${eqY}" x2="1000" y2="${eqY}" stroke="#ffffff45" stroke-width="1.2"/>`;
  const [primeX] = gmProject(0, 0);
  out += `<line x1="${primeX}" y1="0" x2="${primeX}" y2="500" stroke="#ffffff45" stroke-width="1.2"/>`;
  out += `<rect x="0.5" y="0.5" width="999" height="499" fill="none" stroke="#ffffff20" stroke-width="1"/>`;

  g.innerHTML = out;
  gmSvgReady = true;
}

/** Ajoute un point qui pulse a la position d un pays, puis se retire seul. */
const gmWarnedMissingCountries = new Set();
function gmPulse(country, category) {
  const coords = GM_COUNTRY_COORDS[country];
  if (!coords) {
    // Signale une seule fois par code manquant (pas a chaque pulsation) :
    // un signalement precedent decrivait des statistiques qui montent sans
    // plus aucun point affiche, symptome exact d un code pays present dans
    // le vrai trafic mais absent de cette table — desormais visible dans la
    // console plutot que silencieux.
    if (!gmWarnedMissingCountries.has(country)) {
      gmWarnedMissingCountries.add(country);
      console.warn('[carte] code pays sans coordonnee connue, pulsation ignoree :', country);
    }
    return;
  }
  const [x, y] = gmProject(coords[0], coords[1]);
  const svg = document.getElementById('gm-svg');
  if (!svg) return;
  const color = GM_CATEGORY_COLOR[category] || GM_CATEGORY_COLOR.unknown;
  const NS = 'http://www.w3.org/2000/svg';

  const dot = document.createElementNS(NS, 'circle');
  dot.setAttribute('cx', x); dot.setAttribute('cy', y); dot.setAttribute('r', '3');
  dot.setAttribute('fill', color);
  svg.appendChild(dot);

  // API Web Animations plutot que SMIL (<animate>). C est LA cause du bug
  // « les points s affichent a la premiere vue, puis plus rien » : en SMIL,
  // l attribut `begin` est relatif a la timeline du DOCUMENT, pas a
  // l insertion de l element. Un `begin="4.5s"` avec `fill="freeze"` sur un
  // point insere alors que la page est ouverte depuis plus de 4,5 s voyait
  // donc son animation deja terminee — le point etait cree, ajoute au DOM,
  // puis fige immediatement a opacity:0. Invisible, sans la moindre erreur,
  // et toujours bien present si l on compte les <circle> du DOM : c est
  // exactement ce que faisaient les tests precedents, qui mesuraient donc
  // la mauvaise chose. La timeline de l API Web Animations, elle, part du
  // moment de l appel — le comportement est identique quel que soit l age
  // de la page.
  const DOT_LIFETIME_MS = 6000;
  dot.animate(
    [{ opacity: 1, offset: 0 }, { opacity: 1, offset: 0.75 }, { opacity: 0, offset: 1 }],
    { duration: DOT_LIFETIME_MS, fill: 'forwards' }
  );

  // L anneau reste un bref eclat au moment de l arrivee.
  const ring = document.createElementNS(NS, 'circle');
  ring.setAttribute('cx', x); ring.setAttribute('cy', y); ring.setAttribute('r', '3');
  ring.setAttribute('fill', 'none'); ring.setAttribute('stroke', color); ring.setAttribute('stroke-width', '1.5');
  svg.appendChild(ring);
  ring.animate(
    [{ r: '3px', opacity: 1 }, { r: '18px', opacity: 0 }],
    { duration: 1600, fill: 'forwards' }
  );

  setTimeout(() => { ring.remove(); }, 1700);
  setTimeout(() => { dot.remove(); }, DOT_LIFETIME_MS + 100);
}

async function loadGeomap() {
  gmDrawGraticule();
  const status = await api('/analyzer/status').catch(() => null);
  const disabledEl = document.getElementById('geomap-disabled');
  const mainEl = document.getElementById('geomap-main');
  const geoipOk = status?.agent?.geoip?.available;
  if (!status || !status.enabled || !geoipOk) {
    disabledEl.style.display = '';
    mainEl.style.display = 'none';
    return;
  }
  disabledEl.style.display = 'none';
  mainEl.style.display = 'flex';
  await gmLoadVhostOptions();
  // Demande explicitement : les stats et les pulsations partent du moment
  // ou la carte est ouverte, pas d un historique deja ecoule. Le premier
  // sondage n aura donc naturellement rien a montrer, et tout ce qui suit
  // reflete uniquement ce qui se passe reellement pendant que la page est
  // affichee — plus de rejeu d un instantane passe.
  // gmLastSeen part a 0 : c est le premier sondage qui adoptera le numero de
  // sequence courant de l analyzer (voir gmPoll) comme point de depart.
  gmLastSeen = 0;
  gmSkipFirstBatch = true;
  gmRecentDisplay = [];
  await gmPoll();
}

/** Peuple le filtre vhost une seule fois par ouverture de page — pas a chaque sondage. */
async function gmLoadVhostOptions() {
  const sel = document.getElementById('gm-vhost');
  if (!sel || sel.dataset.loaded) return;
  const d = await api('/zones').catch(() => null);
  if (!d?.zones?.length) return;
  for (const z of d.zones) {
    const opt = document.createElement('option');
    opt.value = z.name;
    opt.textContent = z.name;
    sel.appendChild(opt);
  }
  sel.dataset.loaded = '1';
}

/**
 * Changer de vhost repart de zero, meme logique que l ouverture de la page :
 * un vhost qu on vient de selectionner ne doit pas afficher un instantane
 * historique d un AUTRE vhost, ni un melange des deux pendant la transition.
 */
async function gmChangeVhost() {
  gmLastSeen = 0;
  gmSkipFirstBatch = true;
  gmRecentDisplay = [];
  document.getElementById('gm-recent-list').innerHTML = '';
  await gmPoll();
}

async function gmPoll() {
  const mainEl = document.getElementById('geomap-main');
  if (!mainEl || mainEl.style.display === 'none') return;   // page pas active : inutile de sonder
  const qs = new URLSearchParams();
  // Fix (audit finding ANA-09) : le curseur est desormais un numero de
  // sequence d ingestion cote analyzer (sinceSeq/currentSeq), pas une
  // horodate. Comparer le curseur a l horodatage du LOG (precision 1s, et
  // ecrit dans le tampon avec un peu de retard par le tailer) perdait des
  // evenements des que l horloge choisie pour le curseur — meme celle du
  // serveur — passait devant celle du log. Un compteur d ingestion ne peut
  // jamais etre "en avance" sur les evenements qu il numerote.
  if (gmLastSeen) qs.set('sinceSeq', String(gmLastSeen));
  const vhost = document.getElementById('gm-vhost')?.value;
  if (vhost) qs.set('vhost', vhost);
  const d = await api('/analyzer/traffic/recent?' + qs.toString()).catch((err) => {
    console.warn('[carte] echec de la requete /analyzer/traffic/recent :', err);
    return null;
  });
  if (!d) return;
  if (d.reachable === false) {
    console.warn('[carte] analyseur injoignable (reachable:false) — verifier la page Analyse');
    return;
  }

  if (!d.geoipAvailable) {
    console.warn('[carte] geoipAvailable:false — base GeoIP non configuree cote agent');
    document.getElementById('geomap-disabled').style.display = '';
    document.getElementById('geomap-main').style.display = 'none';
    return;
  }

  // Trace volontairement laissee active (pas juste sur erreur) : un sondage
  // qui tourne normalement mais ne renvoie jamais rien de nouveau, versus un
  // sondage qui ne se declenche pas du tout, sont deux causes tres
  // differentes a distinguer immediatement depuis la console — sans ca,
  // impossible de savoir si "aucun point" veut dire "aucun trafic" ou "les
  // donnees arrivent mais ne se dessinent pas".
  console.log(`[carte] sondage : ${(d.events||[]).length} evenement(s) recu(s), sinceSeq=${gmLastSeen||'(aucun)'}`);

  // Premier sondage apres l ouverture de la carte : on ne dessine rien et on
  // ne compte rien, on se contente d adopter le numero de sequence courant de
  // l analyzer comme point de depart. C est ce qui fait reellement partir les
  // statistiques « a partir du chargement de la carte », sans dependre d
  // aucune horloge (fix ANA-09 : voir le commentaire de gmLastSeen ci-dessus).
  if (gmSkipFirstBatch) {
    gmSkipFirstBatch = false;
    if (d.currentSeq) gmLastSeen = d.currentSeq;
    return;
  }

  for (const e of (d.events || [])) {
    // Une exception ici (donnee inattendue, echec SVG) ne doit ni interrompre
    // les evenements suivants de la meme serie, ni disparaitre en silence :
    // sans ce garde, un seul evenement problematique pouvait empecher tous
    // les autres pulses de la boucle de s afficher.
    try { gmPulse(e.country, e.category); }
    catch (err) { console.error('[carte] echec de la pulsation pour', e.country, err); }
    gmRecentDisplay.unshift(e);
  }
  // Fenetre reelle plutot qu un plafond d evenements : un pays vu il y a
  // 20 minutes ne doit plus compter dans « visites des 5 dernieres minutes ».
  // La borne est calculee sur l horloge du SERVEUR (serverTime), la meme qui
  // horodate les evenements — comparer a `Date.now()` du navigateur rendait
  // la fenetre fausse des que les deux horloges divergeaient.
  const now = d.serverTime || Date.now();
  const cutoff = now - GM_WINDOW_MS;
  if (d.currentSeq) gmLastSeen = d.currentSeq;
  gmRecentDisplay = gmRecentDisplay.filter(e => e.ts >= cutoff);

  const total = gmRecentDisplay.length;
  const bots = gmRecentDisplay.filter(e => e.isBot).length;
  const countries = new Set(gmRecentDisplay.map(e => e.country)).size;
  document.getElementById('gm-total').textContent = total;
  document.getElementById('gm-human').textContent = total - bots;
  document.getElementById('gm-bots').textContent = bots;
  document.getElementById('gm-countries').textContent = countries;

  const list = document.getElementById('gm-recent-list');
  list.innerHTML = '';
  if (!gmRecentDisplay.length) {
    const p = document.createElement('div');
    p.style.color = 'var(--text3)';
    p.textContent = t('geomap.recent.empty');
    list.appendChild(p);
  }
  for (const e of gmRecentDisplay.slice(0, 15)) {
    const row = document.createElement('div');
    row.style.cssText = 'display:flex;align-items:center;gap:8px';
    const dot = document.createElement('span');
    dot.className = 'gm-dot';
    dot.style.background = GM_CATEGORY_COLOR[e.category] || GM_CATEGORY_COLOR.unknown;
    row.appendChild(dot);
    const country = document.createElement('span');
    country.style.color = 'var(--text)';
    country.textContent = e.country;
    row.appendChild(country);
    const vhost = document.createElement('span');
    vhost.style.color = 'var(--text3)';
    vhost.textContent = e.vhost || '';
    row.appendChild(vhost);
    const cat = document.createElement('span');
    cat.style.cssText = 'margin-left:auto;color:var(--text3);font-size:11px';
    cat.textContent = gmCategoryLabel(e.category);
    row.appendChild(cat);
    list.appendChild(row);
  }
}
